~()?\"']/g, ' ')\n .replace(/\\s+/g,:
~()?"']/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

/**
 * Enjin Carian & Pertanyaan Semantik berketepatan tinggi
 */
eksport fungsi async searchSentences(
  pertanyaan: rentetan,
  penapis: SearchFilterOptions = {}
): Janji<{ keputusan: SentenceItem[]; jumlah:bilangan; semanticMatches?: SemanticExplanationMatch[] }> {
  const all = menunggu loadSentences();
  const normalizedQuery = normalizeText(query);
  const queryTokens = normalizedQuery ? normalizedQuery.split(' ').filter(Boolean) : [];

  const {
    cefr = 'semua',
    bahagian = 'semua',
    kategori = 'semua',
    subkategori = 'semua',
    tatabahasa = 'semua',
    formaliti = 'semua',
    had = 50,
    offset = 0,
  } = penapis;

  // Pas penapis
  biarkan ditapis = all.filter(s => {
    jika (cefr !== 'semua' && s.cefr !== cefr) mengembalikan palsu;
    jika (bahagian !== 'semua' && s.bahagian !==bahagian) mengembalikan palsu;
    jika (kategori !== 'semua' && s.kategori !== kategori) mengembalikan palsu;
    jika (subkategori !== 'semua' && s.subkategori !== subkategori) mengembalikan palsu;
    jika (tatabahasa !== 'semua' && !s.grammar.toLowerCase().includes(grammar.toLowerCase())) return false;
    jika (formaliti !== 'semua' && s.formality.toLowerCase() !== formality.toLowerCase()) return false;
    kembali benar;
  });

  jika (!normalizedQuery) {
    const total = ditapis.panjang;
    const penomboran = ditapis. slice(offset, offset + had);
    pulangkan { keputusan: penomboran, jumlah };
  }

  // Algoritma pemarkahan
  interfaceScoredItem {
    item:SentenceItem;
    markah:nombor;
    aspek: SemanticExplanationMatch['matchedAspect'];
  }

  const scored: ScoredItem[] = [];

  untuk (const s of filtered) {
    biarkan skor = 0;
    biarkan matchedAspect: SemanticExplanationMatch['matchedAspect'] = 'english';

    const normEn = normalizeText(s.english);
    const normEg = normalizeText(s.arabicEg);
    const normFusha = normalizeText(s.arabicFusha);
    const normGrammar = normalizeText(s.grammar);
    const normPurpose = normalizeText(s.purpose);

    // Padanan ayat penuh tepat
    if (normEn === normalizedQuery) {
      markah += 100;
      matchedAspect = 'english';
    } else if (normEg === normalizedQuery) {
      markah += 95;
      matchedAspect = 'arab-cth';
    } else if (normFusha === normalizedQuery) {
      markah += 90;
      matchedAspect = 'arab-fusha';
    }

    //Subrentetan mengandungi
    if (normEn.includes(normalizedQuery)) {
      markah += 50;
      matchedAspect = 'english';
    } else if (normEg.includes(normalizedQuery)) {
      markah += 45;
      matchedAspect = 'arab-cth';
    } else if (normFusha.includes(normalizedQuery)) {
      markah += 40;
      matchedAspect = 'arab-fusha';
    } else if (normGrammar.includes(normalizedQuery)) {
      markah += 35;
      matchedAspect = 'tatabahasa';
    } else if (normPurpose.includes(normalizedQuery)) {
      markah += 30;
      matchedAspect = 'konsep';
    }

    // Perlawanan token
    biarkan tokenMatches = 0;
    for (const token of queryTokens) {
      if (normEn.includes(token)) tokenMatches += 5;
      if (normEg.includes(token)) tokenMatches += 4;
      if (normFusha.includes(token)) tokenMatches += 3;
      if (s.vocabulary.some(v => normalizeText(v).includes(token))) tokenMatches += 4;
      jika (s.tags.some(t => normalizeText(t).includes(token))) tokenMatches += 3;
    }
    skor += tokenMatches;

    jika (skor > 0) {
      scored.push({ item: s, score, aspect: matchedAspect });
    }
  }

  scored.sort((a, b) => b.skor - a.skor);

  // Penjelasan semantik sepadan untuk item teratas
  const semanticMatches: SemanticExplanationMatch[] = scored.slice(0, 5).map(s => {
    biarkan nuansa = '';
    jika (s.item.grammar.toLowerCase().includes('past continuous')) {
      nuansa = 'The past continuous tense menunjukkan bahawa sesuatu peristiwa sedang berlangsung pada masa tertentu pada masa lalu.';
    } lain jika (s.item.grammar.toLowerCase().includes('present perfect continuous continuous')) {
      nuansa = 'The present perfect continuous tense menekankan masa dari masa lalu dan berterusan sehingga saat bercakap.';
    } lain jika (s.item.grammar.toLowerCase().includes('future perfect')) {
      nuansa = 'The future perfect tense menyatakan bahawa sesuatu peristiwa akan diselesaikan sebelum masa tertentu pada masa hadapan.';
    } lain jika (s.item.grammar.toLowerCase().includes('indirect')) {
      nuansa = 'Bentuk permintaan tidak langsung adalah puncak etika diplomatik dalam komunikasi Inggeris.';
    }
    kembali {
      ayat: s.item,
      Skor persamaan: Math.min(100, s.skor),
      nuanceExplanationAr: nuansa,
      padananAspek: s.aspek,
    };
  });

  jumlah const = markah. panjang;
  const penomboran = scored.slice(offset, offset + had).map(s => s.item);

  kembali {
    keputusan: penomboran,
    jumlah,
    semanticMatches,
  };
}

